CREATE DATABASE IF NOT EXISTS moneytrack CHARACTER SET utf8mb4;
USE moneytrack;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE budget_settings(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL UNIQUE,monthly_salary DECIMAL(12,2) NOT NULL DEFAULT 0,salary_day TINYINT NOT NULL DEFAULT 1,emergency_reserve DECIMAL(12,2) NOT NULL DEFAULT 0,daily_spending_limit DECIMAL(12,2) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
 CONSTRAINT chk_day CHECK(salary_day BETWEEN 1 AND 31),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE incomes(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,source_name VARCHAR(120) NOT NULL,amount DECIMAL(12,2) NOT NULL CHECK(amount>=0),income_date DATE NOT NULL,income_type ENUM('salary','other') NOT NULL DEFAULT 'other',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,income_date),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE commitments(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,name VARCHAR(120) NOT NULL,amount DECIMAL(12,2) NOT NULL CHECK(amount>=0),category VARCHAR(60) NOT NULL DEFAULT 'Bills',due_date DATE NOT NULL,recurrence ENUM('monthly','weekly','yearly','one-time') NOT NULL DEFAULT 'monthly',payment_status ENUM('pending','paid') NOT NULL DEFAULT 'pending',paid_date DATE NULL,notes VARCHAR(255) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id,due_date),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE expenses(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,amount DECIMAL(12,2) NOT NULL CHECK(amount>0),category VARCHAR(60) NOT NULL,description VARCHAR(255) NULL,expense_date DATE NOT NULL,payment_method VARCHAR(40) NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,INDEX(user_id,expense_date),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE notifications(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,title VARCHAR(120) NOT NULL,message VARCHAR(500) NOT NULL,notification_type VARCHAR(40) NOT NULL,is_read TINYINT(1) NOT NULL DEFAULT 0,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,INDEX(user_id,is_read),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE monthly_plans(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,plan_month CHAR(7) NOT NULL,planned_budget DECIMAL(12,2) NOT NULL DEFAULT 0,emergency_reserve_goal DECIMAL(12,2) NOT NULL DEFAULT 0,notes TEXT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,UNIQUE(user_id,plan_month),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
